-- Migration: Integrate Master YouTube Educator Directory (Edition 0.1.0)
-- Timestamp: 2026-10-26

-- 1. Add extended columns to public.master_educators if not present
ALTER TABLE IF EXISTS public.master_educators
  ADD COLUMN IF NOT EXISTS channel_handle TEXT,
  ADD COLUMN IF NOT EXISTS entity_type TEXT,
  ADD COLUMN IF NOT EXISTS access_model TEXT,
  ADD COLUMN IF NOT EXISTS region_group TEXT,
  ADD COLUMN IF NOT EXISTS corroboration_level TEXT,
  ADD COLUMN IF NOT EXISTS confidence_level TEXT,
  ADD COLUMN IF NOT EXISTS taxonomy_subject_id TEXT,
  ADD COLUMN IF NOT EXISTS taxonomy_domain_id TEXT,
  ADD COLUMN IF NOT EXISTS intents TEXT[] DEFAULT '{}',
  ADD COLUMN IF NOT EXISTS exam_ids TEXT[] DEFAULT '{}',
  ADD COLUMN IF NOT EXISTS board_ids TEXT[] DEFAULT '{}',
  ADD COLUMN IF NOT EXISTS representative_video_urls TEXT[] DEFAULT '{}',
  ADD COLUMN IF NOT EXISTS channel_key TEXT;

-- 2. Ensure indexes for efficient directory querying
CREATE INDEX IF NOT EXISTS idx_master_educators_handle ON public.master_educators (channel_handle);
CREATE INDEX IF NOT EXISTS idx_master_educators_key ON public.master_educators (channel_key);
CREATE INDEX IF NOT EXISTS idx_master_educators_exam_ids ON public.master_educators USING gin (exam_ids);
CREATE INDEX IF NOT EXISTS idx_master_educators_board_ids ON public.master_educators USING gin (board_ids);

-- 3. Upsert All 96 Master Directory Educators

